H.tex = (el, tex) => { el.innerHTML = tex; if (window.SID) SID.typeset([el]); };
H.texLater = (() => { const timers = new WeakMap(); return (el, tex, ms = 180) => { clearTimeout(timers.get(el));
  timers.set(el, setTimeout(() => H.tex(el, tex), ms)); }; })();
H.plotBox = (parent, opts, cls) => { const d = H.div(parent, cls || 'w-plot'); return Plot(d, opts); };
H.rerender = (P) => { P.clear(); P.drawAxes(); };
H.sleep = (ms) => new Promise(r => setTimeout(r, ms));
H.C = ['a1', 'a2', 'a3', 'a4', 'a5', 'a6'];
H.mtx = (A, d = 3) => LA.tex(A, d);
